window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-641544951dd0ed04"]={"versions": [{"id": "FIG-641544951dd0ed04", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Paketierungsdiagramm im Architekturkontext des AUTOSAR Adaptive Platform Update and Configuration Management (UCM). Das Diagramm visualisiert den hierarchischen Aufbau und die Kapselung von Software Packages sowie deren Zusammenfassung und kryptografische Autorisierung auf Gesamtfahrzeugebene durch ein übergeordnetes Vehicle Package.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind drei Hauptartefakte mit innerer Container- und Dokumentstruktur:</p>\n<ul class=\"fig-list\"><li><strong>Software Package A &amp; Software Package B</strong>:\n<ul class=\"fig-list\"><li>Jeweils ein äußerer Dokumentenrahmen mit zugeordnetem <em>Authentication tag</em> am Fuß.\n</li><li>Darin eingebettet ein <em>Signed container</em>, bestehend aus:\n<ul class=\"fig-list\"><li>Nutzdaten-Container mit <em>Executables</em>, <em>Data</em> und <em>Manifests</em>.\n</li><li>Einem separaten <em>Software Package Manifest</em>.\n</li></ul>\n</li></ul>\n</li><li><strong>Vehicle Package</strong>:\n<ul class=\"fig-list\"><li>Äußerer Paketrahmen mit zugeordnetem <em>OEM authentication tag</em> am Fuß.\n</li><li>Darin eingebettet ein <em>Signed container</em>, der aggregiert:\n<ul class=\"fig-list\"><li><em>Software Package manifest A</em>\n</li><li><em>Software Package manifest B</em>\n</li><li><em>Vehicle Package manifest</em>\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt ein statisches Kompositions- und Integritätsmodell für Ausrollungs- und Update-Prozesse:</p>\n<ul class=\"fig-list\"><li>Einzelne Software Packages kapseln ausführbaren Code, Daten und lokale Manifeste und werden jeweils separat über ihren individuellen <em>Signed container</em> sowie das <em>Authentication tag</em> kryptografisch gesichert.\n</li><li>Für die fahrzeugweite Koordination und Freigabe werden die einzelnen Software Package Manifeste (A und B) im Vehicle Package zusammengeführt und mit dem <em>Vehicle Package manifest</em> in einem übergeordneten <em>Signed container</em> gebündelt.\n</li><li>Das gesamte Vehicle Package wird über das <em>OEM authentication tag</em> durch den Fahrzeughersteller authentifiziert, wodurch eine fahrzeugweite Integritätskette vom Gesamtfahrzeug-Update bis zu den einzelnen Software-Clustern sichergestellt wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Für die Implementierung von UCM-Master- und Subordinate-Mechanismen verbindlich: Ein Vehicle Package enthält auf oberster Ebene keine vollständigen Binärdaten der einzelnen Software Packages, sondern aggregiert deren Manifeste zusammen mit dem fahrzeugspezifischen Kampagnen-Manifest (<em>Vehicle Package manifest</em>).\n</li><li>Die Signatur-/Integritätsprüfung muss zweistufig erfolgen: Validierung des Vehicle Packages gegen das OEM-Zertifikat über das <em>OEM authentication tag</em> sowie autarke Validierung der eigentlichen Software-Paket-Inhalte über das jeweilige <em>Authentication tag</em> bzw. die Signaturen der <em>Signed container</em>.\n</li><li>Software Package Manifeste müssen konsistent zwischen dem Einzelpaket und dem übergeordneten Vehicle Package referenziert bzw. repliziert werden.\n</li></ul>"}, {"id": "FIG-0cf2e6ff214d6e22", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Paketierungsdiagramm im Architekturkontext des AUTOSAR Adaptive Platform Update and Configuration Management (UCM). Das Diagramm visualisiert den hierarchischen Aufbau und die Kapselung von Software Packages sowie deren Zusammenfassung und kryptografische Autorisierung auf Gesamtfahrzeugebene durch ein übergeordnetes Vehicle Package.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind drei Hauptartefakte mit innerer Container- und Dokumentstruktur:</p>\n<ul class=\"fig-list\"><li><strong>Software Package A &amp; Software Package B</strong>:\n<ul class=\"fig-list\"><li>Jeweils ein äußerer Dokumentenrahmen mit zugeordnetem <em>Authentication tag</em> am Fuß.\n</li><li>Darin eingebettet ein <em>Signed container</em>, bestehend aus:\n<ul class=\"fig-list\"><li>Nutzdaten-Container mit <em>Executables</em>, <em>Data</em> und <em>Manifests</em>.\n</li><li>Einem separaten <em>Software Package Manifest</em>.\n</li></ul>\n</li></ul>\n</li><li><strong>Vehicle Package</strong>:\n<ul class=\"fig-list\"><li>Äußerer Paketrahmen mit zugeordnetem <em>OEM authentication tag</em> am Fuß.\n</li><li>Darin eingebettet ein <em>Signed container</em>, der aggregiert:\n<ul class=\"fig-list\"><li><em>Software Package manifest A</em>\n</li><li><em>Software Package manifest B</em>\n</li><li><em>Vehicle Package manifest</em>\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt ein statisches Kompositions- und Integritätsmodell für Ausrollungs- und Update-Prozesse:</p>\n<ul class=\"fig-list\"><li>Einzelne Software Packages kapseln ausführbaren Code, Daten und lokale Manifeste und werden jeweils separat über ihren individuellen <em>Signed container</em> sowie das <em>Authentication tag</em> kryptografisch gesichert.\n</li><li>Für die fahrzeugweite Koordination und Freigabe werden die einzelnen Software Package Manifeste (A und B) im Vehicle Package zusammengeführt und mit dem <em>Vehicle Package manifest</em> in einem übergeordneten <em>Signed container</em> gebündelt.\n</li><li>Das gesamte Vehicle Package wird über das <em>OEM authentication tag</em> durch den Fahrzeughersteller authentifiziert, wodurch eine fahrzeugweite Integritätskette vom Gesamtfahrzeug-Update bis zu den einzelnen Software-Clustern sichergestellt wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Für die Implementierung von UCM-Master- und Subordinate-Mechanismen verbindlich: Ein Vehicle Package enthält auf oberster Ebene keine vollständigen Binärdaten der einzelnen Software Packages, sondern aggregiert deren Manifeste zusammen mit dem fahrzeugspezifischen Kampagnen-Manifest (<em>Vehicle Package manifest</em>).\n</li><li>Die Signatur-/Integritätsprüfung muss zweistufig erfolgen: Validierung des Vehicle Packages gegen das OEM-Zertifikat über das <em>OEM authentication tag</em> sowie autarke Validierung der eigentlichen Software-Paket-Inhalte über das jeweilige <em>Authentication tag</em> bzw. die Signaturen der <em>Signed container</em>.\n</li><li>Software Package Manifeste müssen konsistent zwischen dem Einzelpaket und dem übergeordneten Vehicle Package referenziert bzw. repliziert werden.\n</li></ul>"}], "trans": [{"from": "FIG-641544951dd0ed04", "to": "FIG-0cf2e6ff214d6e22", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
